export function resolveRpcReply(service: string, op: string, variant: string | null | undefined, payload: Uint8Array): Uint8Array {
  if (service === "TallyOwlIngest" && op === "capture") {
    switch (variant) {
      case "CaptureResponse": return payload;
      case "ServiceError": { const tree = decode(payload); throw new ServiceErrorTypeRefusal(fromServiceErrorTypeCborValue(tree)); }
      default: throw new Error(`invalid RPC reply variant ${variant}`);
    }
  }
  if (service === "TallyOwlIngest" && op === "capture-critical") {
    switch (variant) {
      case "CaptureCriticalResponse": return payload;
      case "ServiceError": { const tree = decode(payload); throw new ServiceErrorTypeRefusal(fromServiceErrorTypeCborValue(tree)); }
      default: throw new Error(`invalid RPC reply variant ${variant}`);
    }
  }
  if (service === "TallyOwlIngest" && op === "policy-version") {
    switch (variant) {
      case "PolicyVersionResponse": return payload;
      case "ServiceError": { const tree = decode(payload); throw new ServiceErrorTypeRefusal(fromServiceErrorTypeCborValue(tree)); }
      default: throw new Error(`invalid RPC reply variant ${variant}`);
    }
  }
  if (service === "TallyOwlAlertReceiver" && op === "notify") {
    switch (variant) {
      case "AlertNotifyResponse": return payload;
      case "ServiceError": { const tree = decode(payload); throw new ServiceErrorTypeRefusal(fromServiceErrorTypeCborValue(tree)); }
      default: throw new Error(`invalid RPC reply variant ${variant}`);
    }
  }
  return payload;
}
